import{c as a,Q as e,j as i,m as l}from"./chunks/framework.DOi4mjdC.js";const n=JSON.parse('{"title":"C API","description":"","frontmatter":{},"headers":[{"level":1,"title":"C API","slug":"c-api"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"},{"level":2,"title":"API类型介绍","slug":"api类型介绍"},{"level":2,"title":"关键字","slug":"关键字"},{"level":2,"title":"流水类型","slug":"流水类型"},{"level":2,"title":"API列表","slug":"api列表"}],"relativePath":"api/SIMD-API/c_api/README.md","filePath":"api/SIMD-API/c_api/README.md"}'),r={name:"api/SIMD-API/c_api/README.md"};function d(s,t,h,o,_,c){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="c-api" tabindex="-1">C API <a class="header-anchor" href="#c-api" aria-label="Permalink to &quot;C API&quot;">​</a></h1><p>C API开放芯片完备编程能力，支持<a href="./general_instruction.html#以数组方式申请内存">以数组形式分配内存</a>，一般基于指针编程。提供与业界一致的C语言编程体验。</p><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>包含asc_simd.h文件来调用C API相应接口。如无特殊说明，包含该头文件即可满足接口调用需求。 若API文档中有特殊说明，则应遵循API的具体说明。</p></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;c_api/asc_simd.h&quot;</span></span></code></pre></div><h2 id="api类型介绍" tabindex="-1">API类型介绍 <a class="header-anchor" href="#api类型介绍" aria-label="Permalink to &quot;API类型介绍&quot;">​</a></h2><ul><li>前n个数据计算：该类型API在计算时采用“紧密排布”的数据读取方式，即从起始位置开始，按顺序连续获取所需数据。例如，若需处理N个数据，则从源操作数的第0个位置开始，依次取至第N-1个位置。</li><li>高维切分计算：该类型API按照设定的规则“跳过部分数据”。适合处理需要间隔采样的场景，灵活度高，但需要额外配置相关参数。</li><li>同步计算：该类型API内部自动插入同步操作，易用性更强。</li></ul><h2 id="关键字" tabindex="-1">关键字 <a class="header-anchor" href="#关键字" aria-label="Permalink to &quot;关键字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>描述</th></tr></thead><tbody><tr><td>__gm__</td><td>存储空间定义修饰符，表示被修饰的变量位于Global Memory地址空间。</td></tr><tr><td>__ubuf__</td><td>存储空间定义修饰符，表示被修饰的变量位于Unified Buffer地址空间。</td></tr><tr><td>__aicore__</td><td>执行空间限定符。表示该函数只能在Ai Core上执行。</td></tr></tbody></table><h2 id="流水类型" tabindex="-1">流水类型 <a class="header-anchor" href="#流水类型" aria-label="Permalink to &quot;流水类型&quot;">​</a></h2><p>NPU内部有不同的计算单元，在计算时往往需要把计算数据搬运到计算单元上。不同计算单元上的计算过程、数据搬运过程可划分为不同的流水线。在AI Core上执行的操作会被分配到不同的流水线(PIPE)上执行，包括以下几种：</p><ul><li>PIPE_S：标量流水线，负责指令分发和标量计算。</li><li>PIPE_V：矢量计算流水线。</li><li>PIPE_M：矩阵计算流水线。</li><li>PIPE_MTE1：搬运操作。包括从L1 Buffer到L0A Buffer或L0B Buffer，从L1 Buffer到UB的搬运操作和L0A Buffer或L0B Buffer的初始化操作。</li><li>PIPE_MTE2：搬运操作。包括从GM到L1 Buffer、从GM到L0A Buffer或L0B Buffer、从GM到UB的搬运操作和L1 Buffer的初始化操作。</li><li>PIPE_MTE3：搬运操作。包括从UB到GM，从UB到L1 Buffer的操作。</li><li>PIPE_FIX：Fixpipe流水线。</li><li>PIPE_ALL：所有流水线。</li></ul><p>可通过<a href="./c_api_list.html#同步控制">同步控制</a>类API控制同一流水线内的运行顺序和不同流水线建的执行顺序。</p><h2 id="api列表" tabindex="-1">API列表 <a class="header-anchor" href="#api列表" aria-label="Permalink to &quot;API列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目录</th></tr></thead><tbody><tr><td><a href="./c_api_list.html#数据结构">数据结构</a></td></tr><tr><td><a href="./c_api_list.html#矢量计算">矢量计算</a></td></tr><tr><td><a href="./c_api_list.html#数据搬运">数据搬运</a></td></tr><tr><td><a href="./c_api_list.html#同步控制">同步控制</a></td></tr><tr><td><a href="./c_api_list.html#系统变量">系统变量</a></td></tr><tr><td><a href="./c_api_list.html#原子操作">原子操作</a></td></tr><tr><td><a href="./c_api_list.html#其他操作">其他操作</a></td></tr></tbody></table>',15)])])}const u=a(r,[["render",d]]);export{n as __pageData,u as default};
